from __future__ import annotations

from typing import Any

from profile_repository import ProfileRepository


def update_profile(payload: dict[str, Any], repository: ProfileRepository) -> dict[str, Any]:
    user_id = str(payload.get("user_id", "")).strip()
    email = str(payload.get("email", "")).strip().lower()
    display_name = str(payload.get("display_name", "")).strip()
    timezone = str(payload.get("timezone", "UTC")).strip()

    if not user_id:
        return {"ok": False, "reason": "invalid_user_id"}
    if "@" not in email or "." not in email:
        return {"ok": False, "reason": "invalid_email"}
    if len(display_name) < 2:
        return {"ok": False, "reason": "invalid_display_name"}
    if timezone not in {"UTC", "AEST", "PST", "EST"}:
        return {"ok": False, "reason": "invalid_timezone"}

    existing = repository.get_profile(user_id)
    if existing is None:
        return {"ok": False, "reason": "not_found"}

    updated = dict(existing)
    updated["email"] = email
    updated["display_name"] = display_name
    updated["timezone"] = timezone
    updated["version"] = int(updated.get("version", 1)) + 1
    repository.save_profile(updated)
    return {"ok": True, "reason": "profile_updated", "profile": updated}


def create_invite(payload: dict[str, Any], repository: ProfileRepository) -> dict[str, Any]:
    inviter_id = str(payload.get("inviter_id", "")).strip()
    invitee_email = str(payload.get("invitee_email", "")).strip().lower()
    invitee_name = str(payload.get("invitee_name", "")).strip()
    timezone = str(payload.get("timezone", "UTC")).strip()

    if not inviter_id:
        return {"ok": False, "reason": "invalid_inviter_id"}
    if "@" not in invitee_email:
        return {"ok": False, "reason": "invalid_invitee_email"}
    if len(invitee_name) < 2:
        return {"ok": False, "reason": "invalid_invitee_name"}
    if timezone not in {"UTC", "AEST", "PST"}:
        # Bug: EST accepted in update path but rejected in invite path.
        return {"ok": False, "reason": "invalid_timezone"}

    inviter = repository.get_profile(inviter_id)
    if inviter is None:
        return {"ok": False, "reason": "inviter_not_found"}

    invite = {
        "inviter_id": inviter_id,
        "invitee_email": invitee_email,
        "invitee_name": invitee_name,
        "timezone": timezone,
        "status": "pending",
    }
    repository.save_invite(invite)
    return {"ok": True, "reason": "invite_created", "invite": invite}


def run_batch_updates(payloads: list[dict[str, Any]], repository: ProfileRepository) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    success = 0
    failed = 0
    for payload in payloads:
        result = update_profile(payload, repository)
        results.append(result)
        if result.get("ok"):
            success += 1
        else:
            failed += 1
    return {"success": success, "failed": failed, "results": results}

