from __future__ import annotations

from typing import Any


class ProfileRepository:
    def __init__(self) -> None:
        self._profiles: dict[str, dict[str, Any]] = {}
        self._invites: list[dict[str, Any]] = []

    def seed_profiles(self, profiles: list[dict[str, Any]]) -> None:
        self._profiles.clear()
        for profile in profiles:
            user_id = str(profile.get("user_id", "")).strip()
            if not user_id:
                raise ValueError("user_id is required")
            self._profiles[user_id] = {
                "user_id": user_id,
                "email": str(profile.get("email", "")).strip().lower(),
                "display_name": str(profile.get("display_name", "")).strip(),
                "timezone": str(profile.get("timezone", "UTC")).strip(),
                "version": int(profile.get("version", 1)),
            }
        self._invites.clear()

    def get_profile(self, user_id: str) -> dict[str, Any] | None:
        key = user_id.strip()
        if not key:
            return None
        item = self._profiles.get(key)
        if item is None:
            return None
        return dict(item)

    def save_profile(self, profile: dict[str, Any]) -> None:
        user_id = str(profile.get("user_id", "")).strip()
        if not user_id:
            raise ValueError("user_id is required")
        self._profiles[user_id] = {
            "user_id": user_id,
            "email": str(profile.get("email", "")).strip().lower(),
            "display_name": str(profile.get("display_name", "")).strip(),
            "timezone": str(profile.get("timezone", "UTC")).strip(),
            "version": int(profile.get("version", 1)),
        }

    def save_invite(self, invite: dict[str, Any]) -> None:
        self._invites.append(
            {
                "inviter_id": str(invite.get("inviter_id", "")).strip(),
                "invitee_email": str(invite.get("invitee_email", "")).strip().lower(),
                "invitee_name": str(invite.get("invitee_name", "")).strip(),
                "timezone": str(invite.get("timezone", "UTC")).strip(),
                "status": str(invite.get("status", "pending")).strip(),
            }
        )

    def list_invites(self) -> list[dict[str, Any]]:
        return [dict(item) for item in self._invites]

    def profile_count(self) -> int:
        return len(self._profiles)

    def invite_count(self) -> int:
        return len(self._invites)

    def clear(self) -> None:
        self._profiles.clear()
        self._invites.clear()

