from profile_handlers import create_invite, update_profile
from profile_repository import ProfileRepository


def _repo() -> ProfileRepository:
    repo = ProfileRepository()
    repo.seed_profiles(
        [
            {
                "user_id": "u-1",
                "email": "owner@example.com",
                "display_name": "Owner",
                "timezone": "UTC",
                "version": 2,
            }
        ]
    )
    return repo


def test_happy_path_est_timezone_allowed_consistently():
    repo = _repo()
    update = update_profile(
        {
            "user_id": "u-1",
            "email": "owner@example.com",
            "display_name": "Owner Name",
            "timezone": "EST",
        },
        repo,
    )
    assert update["ok"] is True

    invite = create_invite(
        {
            "inviter_id": "u-1",
            "invitee_email": "new.user@example.com",
            "invitee_name": "New User",
            "timezone": "EST",
        },
        repo,
    )
    assert invite["ok"] is True
    assert invite["reason"] == "invite_created"


def test_edge_case_invalid_email_rejected():
    repo = _repo()
    result = update_profile(
        {
            "user_id": "u-1",
            "email": "not-an-email",
            "display_name": "Name",
            "timezone": "UTC",
        },
        repo,
    )
    assert result["ok"] is False
    assert result["reason"] == "invalid_email"


def test_boundary_condition_display_name_two_chars_allowed():
    repo = _repo()
    result = update_profile(
        {
            "user_id": "u-1",
            "email": "owner@example.com",
            "display_name": "Ab",
            "timezone": "UTC",
        },
        repo,
    )
    assert result["ok"] is True
    assert result["profile"]["display_name"] == "Ab"


def test_unexpected_input_missing_inviter_rejected():
    repo = _repo()
    result = create_invite(
        {
            "inviter_id": "missing",
            "invitee_email": "x@example.com",
            "invitee_name": "X User",
            "timezone": "UTC",
        },
        repo,
    )
    assert result["ok"] is False
    assert result["reason"] == "inviter_not_found"
